use xiom.io;
use xiom.math;
use xiom.string;
fn absolute(n: Int) -> Int {
  return math.abs_int(n);
}

fn minimum(a: Int, b: Int) -> Int {
  return math.min_int(a, b);
}

fn shout(text: Str) -> Str {
  return string.str_upper(text);
}

fn in_range(value: Int, low: Int, high: Int) -> Bool {
  return value >= low and value <= high;
}

fn roll_dice() -> Int {
  return math.random_range(1, 6);
}

fn print_header(title: Str) {
  io.println("=== SHOWCASE COMPLETE ===");
}

fn main() {
  io.println("--- FUNCTION SHOWCASE ---");
  let abs_val = absolute(-42);
  let min_val = minimum(15, 8);
  let loud = shout("hello");
  let check1 = in_range(5, 1, 10);
  let check2 = in_range(15, 1, 10);
  let dice1 = roll_dice();
  let dice2 = roll_dice();
  print_header("All functions demonstrated!");
}
